head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.decl_seq = frame.opener.key_seq;
scwin.vScrenID = "ULDSTF30411.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.initPage = function() {
    $c.stf.showObj(txb_ISUR_CD, false);
    $c.stf.showObj(txb_DECL_SEQ, false);
    if (scwin.decl_seq == '') {
        //신규작성
        scwin.fn_SetNewMode();
        $c.stf.setObjectValue(rdo_ATTACH_DOC_REG_TP_CD, "01");
        $c.stf.showObj(btn_Delete, false);
    } else {
        // 수정화면
        scwin.fn_ReadDecl();
        $c.stf.showObj(img_com_srch, false);
        $c.stf.showObj(btn_Delete, false);
        $c.stf.showObj(btn_Save, false);
        $c.stf.showObj(btn_AddRow, false);
        $c.stf.showObj(btn_DelRow, false);
        txb_DECLR_NM.setReadOnly(true);
        txb_DECLR_NM.style.backgroundColor = '#b9d4f7';
        txb_BIRTHDD.setReadOnly(true);
        txb_BIRTHDD.style.backgroundColor = '#b9d4f7';
    }
};
scwin.fn_SetNewMode = function() {
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NFAITH_DISCLS_DECL_LIST";
    dts_MASTER.Reset();
    dts_MASTER.insertRow();
    dts_FILE_LIST.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NFAITH_DISCLS_DECL_ATTACH";
    dts_FILE_LIST.Reset();
};
scwin.fn_SetCode = function() {
    dts_DECLR_TP.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=DECLR_TP_CD";
    dts_DECLR_TP.Reset();
};
scwin.fn_ReadDecl = function() {
    var url = "/UnfaithfulDesignReport.do?method=readDecl";
    url += "&DECL_SEQ=" + scwin.decl_seq;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
    url = "/UnfaithfulDesignReport.do?method=readDeclAttach";
    url += "&DECL_SEQ=" + scwin.decl_seq;
    dts_FILE_LIST.DataID = encodeURI(url);
    dts_FILE_LIST.Reset();
};
scwin.fn_CheckForm = function() {
    var birthdd = $c.stf.getObjectValue(txb_BIRTHDD);
    if ($c.stf.getObjectValue(txb_DECLR_NM) == "") {
        $c.win.alert("[성명]을 입력하세요.");
        return false;
    }
    if (birthdd == "") {
        $c.win.alert("[생년월일]을 입력하세요.");
        return false;
    } else {
        if (BIRTHDD.length != 8) {
            $c.win.alert("생년월일을 8자리로 입력해주세요. ex)19800312");
            return false;
        }
    }
    if ($c.stf.IsValidEmail($c.stf.getObjectValue(txb_DECLR_EMAIL)) == false) {
        $c.win.alert("[이메일] 정확하지 않습니다.");
        txb_DECLR_EMAIL.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_DECLR_TEL_NO) == "") {
        $c.win.alert("[연락처]를 입력하세요.");
        txb_DECLR_TEL_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_DECLR_FAX_NO) == "") {
        $c.win.alert("[팩스번호]를 입력하세요.");
        txb_DECLR_FAX_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ZIPCD) == "") {
        $c.win.alert("[주소]를 입력하세요.");
        txb_ZIPCD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_DECLR_TP_CD) == "") {
        $c.win.alert("[신고자구분]를 선택하세요.");
        rdo_DECLR_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[종목]을 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txa_DECL_CONTN) == "") {
        $c.win.alert("[위반내용]을 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(rdo_OTHRINST_DECL_YN) == "") {
        $c.win.alert("[동건의 타부서(타기관포함)신고여부]를 선택하세요.");
        rdo_OTHRINST_DECL_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_RECENT_YY3_RWD_YN) == "") {
        $c.win.alert("[동건의신고로인한타부서 포상여부]를 선택하세요.");
        rdo_RECENT_YY3_RWD_YN.focus();
        return false;
    }
    /*
    if(decl_seq == '') {
    	if (getObjectValue(txb_AUTH_YN) != "Y") {
    		alert("실명인증을 하셔야 합니다.");return false;
    	}
    }
    */
    return true;
};
scwin.fn_Save = function() {
    if (scwin.fn_CheckForm()) {
        if (window.confirm("[저장]하시겠습니까?")) {
            gLastJob = "저장";
            var url = "/UnfaithfulDesignReport.do?method=saveNfaithDsclDecl" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER, I:pFile=dts_FILE_LIST)";
            trs_Save.post();
        }
    }
};
scwin.fn_DownLoad = function(row, colid) {
    var filename = dts_FILE_LIST.getCellData(row, "ATTACH_FILE_NM");
    if (filename == "") return;
    if (colid == "ATTACH_FILE_NM") {
        var DECL_SEQ = dts_FILE_LIST.getCellData(row, "DECL_SEQ");
        var DECL_ATTACH_SEQ = dts_FILE_LIST.getCellData(row, "DECL_ATTACH_SEQ");
        var url = "/filedownload.do?gubun=22";
        url += "&decl_seq=" + DECL_SEQ;
        url += "&decl_attach_seq=" + DECL_ATTACH_SEQ;
        location.href = url;
    }
};
scwin.fn_Delete = function() {
    if (window.confirm("[삭제]하시겠습니까?")) {
        txb_DECLR_NM.setValue("");
        gLastJob = "삭제";
        var url = "/UnfaithfulDesignReport.do?method=deleteNfaithDsclDecl" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER)";
        trs_Save.post();
    }
};



//실명인증하는데 사용한다. 처리에서는 실명을 빼기로 해서 여기에서는 사용하지 않는다.
scwin.fn_realNameCert = async function() {
    var nm = $c.stf.getObjectValue(txb_DECLR_NM);
    var reg_no = $c.stf.getObjectValue(txb_RESD_REG_NO);
    if (nm == '') {
        $c.win.alert("이름을 입력하셔야 합니다.");
        return;
    }
    if (reg_no == '') {
        $c.win.alert("주민등록번호를 입력하셔야 합니다.");
        return;
    }
    var url = "/dsclinfo/ULDSTF30412.jsp?NM=" + nm + "&REG_NO=" + reg_no;
    var winTitle = "신규";
    await $c.frame.CreateFrame("ULDSTF30412", url, winTitle, 10, 10, 100, 200, "window", 0, 0, true);
};
scwin.fn_auth = function() {
    $c.win.alert("fn_auth");
};
scwin.fn_SetPar = function(arrPar) {
    txb_ZIPCD.setValue(arrPar[0]);
    txb_ADDR.setValue(arrPar[1]);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
    $c.win.alert(msg);
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.btn_search_onclick = function() {
    $c.lc.fn_PopFindZipCd();
};
scwin.grd_FILE_LIST_OnClick = function(row, colid) {
    scwin.fn_DownLoad(row, colid);
};
scwin.btn_AddRow_onclick = function() {
    if (dts_FILE_LIST.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_FILE_LIST.insertRow();
    btn_File.open();
    if (btn_File.getValue() != "") {
        dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "ATTACH_FILE_NM", btn_File.getValue());
        dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "FILEURL", btn_File.getValue());
    } else {
        $c.cp.removeRow(dts_FILE_LIST, dts_FILE_LIST.getRowPosition());
    }
    btn_File.setValue("");
};
scwin.btn_DelRow_onclick = function() {
    $c.cp.removeRow(dts_FILE_LIST, dts_FILE_LIST.getRowPosition());
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_ABBRV);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txb_DECL_SEQ, $c.stf.getObjectValue(txb_DECL_SEQ));
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    scwin.fn_SetCode();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.initPage();
};
